class Node:
    def __init__(self, x):
        self.val = x
        self.next = None

class Solution:
    def reverseList(self, head):
        prev, curr = None, head
        while curr:
            curr.next, prev, curr  = prev, curr, curr.next
        return prev

# Example of usage:
node1 = Node(1)
node2 = Node(2)
node3 = Node(3)

node1.next, node2.next, node3.next = node2, node3, None

solution = Solution()
head = solution.reverseList(node1)
while head:
    print(head.val)
    head = head.next
